 let bi=-1,bd=1e9;for(let k=0;k<N.length;k++){const dx=N[k][0]-s.x;if(dx>2||dx<-2)continue;const d=Math.hypot(dx,N[k][1]-s.y);if(d<bd){bd=d;bi=k;}}
 const names=bi<0?[]:[...new Set(adj[bi].map(ei=>(NM[EDG[ei][4]]||'').split('@')[0]).filter(n=>n&&!/ramp|Local road|terminal|access/i.test(n)))];
