  if(v===DEST){const dd=Math.hypot(cur[0]-B[0],cur[1]-B[1]);if(dd<.3)break;legs.push({pts:[cur,[B[0],B[1]]],t:'walk'});steps.push({t:'walk',mi:dd*1.25/12,min:walkMin(dd),to:null});mi+=dd*1.25/12;break;}
